questions.push(
  question("BIO_R4_Q_S088_01", "BIO_R4_S088", "foundation", 0, "內分泌腺所分泌、可調節生理活動的化學訊息稱為什麼？", ["激素", "汗液", "唾液", "膽汁"], ["激素是內分泌腺分泌的化學訊息。", "汗液經汗腺導管到皮膚表面。", "唾液由唾液腺經導管送入口腔。", "膽汁經膽管進入消化道，並非此定義。"], ["題幹直接描述內分泌化學訊息，答案為激素。", "汗液排到體表、唾液進入口腔、膽汁進入消化道，三者都不是由內分泌腺送入血液的化學訊息。"], ["辨識"], "概念定義", ["把所有分泌物都當激素"]),
  question("BIO_R4_Q_S088_02", "BIO_R4_S088", "foundation", 1, "激素離開內分泌腺後，主要進入何處而被運送到其他部位？", ["骨骼空腔", "血液循環", "消化道管腔", "皮膚表面"], ["骨骼不是激素的一般運送通道。", "激素進入微血管後隨血液循環運送。", "進入消化道常是有導管分泌物的去向。", "皮膚表面是汗液等分泌物的去向。"], ["內分泌的重要特徵是分泌物進入血液，而非走導管。", "「血液循環」符合由腺體到遠處目標的主要運送方式。"], ["辨識"], "路徑判斷", ["以為激素沿導管運送"]),
  question("BIO_R4_Q_S088_03", "BIO_R4_S088", "foundation", 2, "下列哪個構造負責把已進入血液的激素運到全身各處？", ["消化系統", "骨骼系統", "循環系統", "表皮角質層"], ["消化系統主要處理食物與吸收養分。", "骨骼系統提供支撐與保護，不運送激素。", "循環系統的血液可運送激素到不同部位。", "表皮角質層提供保護，並非體內運輸網。"], ["題目問血液中的物質運送，直接對應循環系統。", "消化系統處理食物，骨骼系統支撐身體，表皮角質層保護體表；這些功能都不能取代血液的全身運輸。"], ["辨識"], "系統功能", ["混淆器官系統分工"]),
  question("BIO_R4_Q_S088_04", "BIO_R4_S088", "standard", 3, "下列哪項最能區分內分泌腺與汗腺的分泌方式？", ["兩者細胞都含有水", "兩者都位於人體內", "兩者都能產生分泌物", "激素進入血液，汗液經導管到皮膚"], ["含水不是兩類分泌方式的關鍵差異。", "汗腺也在皮膚內，位置敘述不能完成分類。", "能分泌是共同點，沒有指出運送路徑。", "此敘述正確比較血液運送與導管排出。"], ["分類關鍵是分泌物去向，「激素進入血液，汗液經導管到皮膚」完整呈現。", "細胞含水、位於人體內及能產生分泌物都是兩類腺體可共有的情形，只有血液與導管的去向能區分分泌方式。"], ["比較"], "雙構造", ["只看腺體名稱分類"]),
  question("BIO_R4_Q_S088_05", "BIO_R4_S088", "standard", 0, "某細胞群分泌物進入附近微血管，再影響遠處器官。此細胞群最可能具有哪種功能？", ["內分泌功能", "磨碎食物功能", "形成骨骼槓桿", "接收光刺激功能"], ["進入血液並影響遠處符合內分泌特徵。", "磨碎食物需要牙齒與肌肉等構造。", "骨骼槓桿與化學訊息運送不同。", "感光受器接收光，不以分泌遠距訊息為主。"], ["由分泌物進入微血管且有遠距作用，可判為內分泌。", "「內分泌功能」同時符合分泌與循環運送兩個條件。"], ["應用"], "功能情境", ["忽略分泌物去向"]),
  question("BIO_R4_Q_S088_06", "BIO_R4_S088", "standard", 1, "若某內分泌腺仍能製造激素，但附近血流完全受阻，最直接影響為何？", ["激素一定變成神經", "激素難以正常運往遠處目標", "所有目標細胞立即消失", "汗液無法排到皮膚"], ["化學訊息不會因血流受阻而變成神經。", "缺少血液流動會妨礙激素離開局部並遠距運送。", "血流受阻不表示所有目標細胞立即消失。", "汗液排出屬汗腺導管功能，與題述腺體不同。"], ["製造功能仍在而運輸受阻，直接問題應是遠距送達。", "血流受阻會妨礙激素運送，卻不會把激素變成神經、讓目標細胞立即消失，也不會直接阻斷汗腺導管。"], ["因果推論"], "路徑中斷", ["混淆製造與運送"]),
  question("BIO_R4_Q_S088_07", "BIO_R4_S088", "standard", 2, "關於激素分泌與運送，下列敘述何者正確？", ["激素都由血球製造", "激素只留在分泌腺內", "內分泌腺分泌後可由血液運送", "激素必須經皮膚導管到目標"], ["血球主要負責運輸等功能，不製造所有激素。", "激素若只留在腺內就無法完成遠距訊息作用。", "此敘述符合內分泌與循環系統合作。", "皮膚導管不是激素到體內目標的一般路徑。"], ["「內分泌腺分泌後可由血液運送」正確區分分泌者與運送者。", "激素由內分泌腺製造、離腺後可隨血液前往目標；血球不是所有激素的來源，腺內滯留與皮膚導管也不是一般運送路徑。"], ["理解"], "概念判斷", ["把血液當成激素製造者"]),
  question("BIO_R4_Q_S088_08", "BIO_R4_S088", "advanced", 3, "實驗把某腺體分泌液直接導到體外，血中相關訊息量隨後下降。此腺體原本最可能如何傳遞訊息？", ["沿骨骼內部傳到肌肉", "經耳道傳到腦", "經消化道直接到全身", "分泌物進入血液後隨循環運送"], ["骨骼不是化學訊息的全身運送管路。", "耳道傳聲波，不能把腺體分泌物送到全身。", "消化道內容物不等於直接進入全身血液。", "導到體外使血中量下降，支持原本進入血液。"], ["操弄分泌物去向後血中量下降，支持循環運送。", "骨骼、耳道與消化道都不能解釋血中訊息量隨分泌液改道而下降；分泌物原本進入血液才與結果相符。"], ["證據推論"], "實驗情境", ["不依血中資料判斷路徑"]),
  question("BIO_R4_Q_S088_09", "BIO_R4_S088", "advanced", 0, "甲腺分泌物經導管到口腔，乙腺分泌物進入微血管。哪項分類最合理？", ["乙較符合內分泌腺，甲較符合外分泌腺", "甲乙都一定是內分泌腺", "甲較符合內分泌腺，乙一定是汗腺", "甲乙都不能分泌任何物質"], ["乙進血液符合內分泌，甲走導管符合外分泌。", "甲的導管到口腔方式不符合內分泌特徵。", "選項顛倒分類，乙也不能因此判為汗腺。", "兩者都有分泌物，不能說不能分泌。"], ["依有無導管及分泌物去向分類，「乙較符合內分泌腺，甲較符合外分泌腺」正確。", "題幹證據足以分辨分泌方式，但不足指定乙的腺體名稱。"], ["分類推論"], "比較資料", ["以腺字一律歸內分泌"]),
  question("BIO_R4_Q_S088_10", "BIO_R4_S088", "advanced", 1, "研究者在內分泌腺附近與遠處血管都測到同一激素，且附近濃度先升高。哪項解釋較合理？", ["遠處血管製造了腺體", "激素由腺體附近進血，再隨血流到遠處", "激素由皮膚表面逆流進入血管", "所有器官同時自行產生該激素"], ["血管中的激素不能製造一個完整腺體。", "先近後遠符合由分泌處隨循環擴散運送。", "題幹沒有皮膚表面分泌或逆流證據。", "時間差不支持所有器官同時自行製造。"], ["空間與時間順序共同支持腺體為來源、血液為運輸。", "「激素由腺體附近進血，再隨血流到遠處」能解釋兩地都測到且附近較早升高。"], ["資料解釋"], "時空紀錄", ["把運送處誤認為製造處"]),
  question("BIO_R4_Q_S088_11", "BIO_R4_S088", "transfer", 2, "城市把通知放入郵件配送網，再送到不同地址。若類比內分泌，配送網最接近什麼？", ["內分泌腺細胞", "目標細胞受體", "血液循環", "激素作用後的反應"], ["腺細胞較像產生並送出通知的單位。", "受體較像能辨識特定通知的收件裝置。", "配送網負責運送，功能近似血液循環。", "反應是收件後的結果，不是運輸網。"], ["類比應按產生、運送、接收與反應分工。", "「血液循環」準確對應全身運輸角色，不混入訊息內容。"], ["類比", "遷移"], "配送系統", ["把激素與運送系統混為一體"]),
  question("BIO_R4_Q_S088_12", "BIO_R4_S088", "transfer", 3, "藥物貼片將物質送入皮下微血管後產生全身作用，這最能幫助理解激素哪項特性？", ["只能在皮膚表面作用", "一定需要專屬導管到每個器官", "不可能隨血液移動", "進入循環後可被運送到遠處"], ["全身作用顯示物質不只停在皮膚表面。", "血液運送不需要每個器官各有專屬導管。", "題幹正是利用微血管進行運送。", "由局部進入血液後遠距作用，符合此特性。"], ["貼片情境的關鍵是先進微血管再出現遠距效果。", "「進入循環後可被運送到遠處」對應內分泌的循環運送，其他皆與題幹相反。"], ["情境遷移"], "醫療應用", ["認為遠距訊息必靠導管"]),
);

