questions.push(
  question("BIO_R4_Q_S094_01", "BIO_R4_S094", "foundation", 0, "某細胞能對特定激素產生反應，最重要的條件是什麼？", ["具有能接收該激素的受體", "位於分泌腺旁邊", "體積比其他細胞大", "含有最多水分"], ["適合的受體能辨認激素並啟動細胞反應。", "激素可經血液運送，不必只作用於鄰近細胞。", "細胞大小不能決定能否辨認特定激素。", "含水量不是激素作用專一性的主要依據。"], ["標的細胞的判定依據是受體，而不是與分泌腺的距離或細胞外觀。", "激素到達細胞附近仍不保證有作用，細胞必須具備相應接收機制。"], ["受體"], "概念辨識", ["只看激素運送位置"]),
  question("BIO_R4_Q_S094_02", "BIO_R4_S094", "foundation", 1, "同一種激素是否可能同時影響肝臟與肌肉？", ["不可能，激素只能配對一個器官", "可能，只要兩處都有能接收該激素的標的細胞", "不可能，血液無法到達肌肉", "可能，但兩處反應一定完全相同"], ["一種激素可以有分布於多個器官的標的細胞。", "相應受體能讓不同器官的細胞接收同一訊號。", "血液循環可將激素運送到肌肉等組織。", "不同細胞功能不同，接收同一訊號後反應可不同。"], ["激素的作用範圍由標的細胞分布決定，不受單一器官名稱限制。", "多個器官接收同一訊號時，可用不同反應共同完成全身調節。"], ["多重標的"], "概念辨識", ["一種激素只對一個器官"]),
  question("BIO_R4_Q_S094_03", "BIO_R4_S094", "foundation", 2, "關於同一器官接受激素調節的敘述，何者正確？", ["只能接受最先到達的一種激素", "只要有血液就對所有激素反應", "可具有多類受體並整合不同激素訊號", "一旦接受激素就永久維持同一活動"], ["器官細胞可同時具有多種受體，不以到達先後決定全部反應。", "血液運送不代表細胞具有每種激素的受體。", "多類受體使器官可依不同訊號調整活動。", "激素濃度與生理需求會變化，器官活動也可調整。"], ["同一器官通常參與多項生理功能，因此能整合多種調節訊號。", "是否反應仍取決於受體，不能因激素經過就推論器官必定反應。"], ["訊號整合"], "概念辨識", ["一個器官只受一種激素控制"]),
  question("BIO_R4_Q_S094_04", "BIO_R4_S094", "standard", 3, "激素甲使肝臟合成肝糖，也使肌肉增加葡萄糖攝取。這項資料最能支持哪個結論？", ["激素甲只作用於肝臟", "肌肉細胞沒有任何受體", "肝臟與肌肉的反應彼此矛盾", "激素甲可作用於多個組織，協調降低血糖"], ["資料明確顯示肌肉也對激素甲有反應。", "肌肉增加攝取葡萄糖表示能接收相關訊號。", "兩種反應都能減少血液中的葡萄糖，方向協調。", "肝臟與肌肉採取不同方式，卻共同促成血糖下降。"], ["同一激素引起肝臟儲存與肌肉攝取，顯示作用跨越不同組織。", "判斷整體功能時要看共同結果，不必要求每種細胞產生完全相同反應。"], ["跨器官協調"], "資料推論", ["不同反應等於互相矛盾"]),
  question("BIO_R4_Q_S094_05", "BIO_R4_S094", "standard", 0, "某激素進入肝臟血管後，只有部分肝細胞產生反應。最合理的原因是什麼？", ["只有部分肝細胞具有相應受體或反應途徑", "激素只能穿過單數編號的細胞", "沒有反應的細胞必定死亡", "肝臟內完全沒有血液流動"], ["同一器官內不同細胞的受體種類與功能可能不同。", "細胞是否反應與任意編號無關。", "缺乏特定激素反應不表示細胞必定死亡。", "題目已說激素進入肝臟血管，顯示有血液運送。"], ["標的範圍可細到特定細胞，不是只要同屬一個器官就全部反應。", "受體與細胞內途徑的差異，可解釋同一器官內反應不一致。"], ["器官內差異"], "機制推論", ["整個器官反應必然一致"]),
  question("BIO_R4_Q_S094_06", "BIO_R4_S094", "standard", 1, "肝臟在進食後增加肝糖合成，在空腹時增加肝糖分解。這最能說明什麼？", ["肝臟只能接受一種固定訊號", "同一器官可整合不同激素訊號並依需求改變反應", "肝細胞不需要任何受體", "兩種反應必定在同一時間以最大速率進行"], ["進食與空腹狀態需要不同方向的調節。", "多種訊號可使肝臟在不同情境切換儲存與釋放。", "肝細胞須接收調節訊號才能產生相應反應。", "相反反應會依需求調整，不必同時達到最大。"], ["肝臟的活動會隨全身血糖需求改變，反映多種訊號的整合作用。", "儲存與分解方向相反但各有適用情境，並非彼此否定。"], ["肝臟調節"], "情境推論", ["器官只能有單一反應"]),
  question("BIO_R4_Q_S094_07", "BIO_R4_S094", "standard", 2, "研究者要確認激素乙是否同時作用於脂肪與肌肉，最直接的證據是什麼？", ["兩種組織顏色相近", "兩種組織位於身體同一側", "兩種組織都有乙的受體，且加入乙後出現可重複的反應", "血液曾經流過兩種組織"], ["組織顏色不能證明是否接收特定激素。", "身體位置與受體專一性沒有直接關係。", "受體存在及可重複反應共同支持兩者都是標的。", "血液經過只能證明激素可能到達，不能證明細胞有反應。"], ["判定標的需有接收機制與作用結果，兩類證據相互支持最直接。", "只證明激素能到達組織仍不夠，因為沒有受體的細胞可能不反應。"], ["標的證據"], "探究判斷", ["激素到達等於產生作用"]),
  question("BIO_R4_Q_S094_08", "BIO_R4_S094", "advanced", 3, "某激素使骨骼肌增加葡萄糖攝取，卻使肝臟增加肝糖合成。為何兩處反應不同仍可視為協調？", ["因為肌肉與肝臟是同一器官", "因為兩處都沒有受體", "因為激素不會影響血糖", "兩種反應都可減少血中葡萄糖，只是細胞處理方式不同"], ["肌肉與肝臟分屬不同組織，不能視為同一器官。", "兩處出現反應，顯示存在接收訊號的機制。", "增加攝取與儲存都會影響血糖。", "不同細胞執行不同功能，整體結果卻指向血糖下降。"], ["協調不等於細胞反應形式一致，而是各處反應共同達成生理目標。", "肌肉攝取與肝臟儲存都能移除血中葡萄糖，形成互補作用。"], ["整體協調"], "整合推論", ["協調等於反應完全相同"]),
  question("BIO_R4_Q_S094_09", "BIO_R4_S094", "advanced", 0, "藥物只阻斷肌肉細胞對激素甲的受體，肝細胞受體仍正常。加入激素甲後最可能看到什麼？", ["肝臟仍可反應，但肌肉的相關反應減弱", "肝臟與肌肉反應都必定消失", "肌肉反應增強且肝臟死亡", "激素甲立刻變成另一種激素"], ["阻斷僅發生在肌肉，肝細胞仍能接收訊號。", "肝細胞受體正常，不應推論肝臟作用必定消失。", "受體被阻斷通常使反應減弱，不會因此增強。", "受體阻斷不會改變激素的化學身分。"], ["這個結果能顯示同一激素在不同組織的作用可被分別改變。", "作用差異應依各組織受體狀態解釋，不能把局部阻斷推成全身失效。"], ["局部受體阻斷"], "實驗推論", ["局部異常等於全身無反應"]),
  question("BIO_R4_Q_S094_10", "BIO_R4_S094", "advanced", 1, "若某器官同時具有甲、乙兩種激素的受體，最合理的推論為何？", ["甲與乙必定由同一腺體分泌", "此器官可能依兩種訊號及其濃度調整活動", "兩種受體一定互相抵消", "此器官對其他所有訊號都不會反應"], ["不同激素可由不同內分泌腺分泌。", "具有兩種受體表示細胞有機會接收並整合兩種訊號。", "受體存在不代表作用必然互相抵消。", "題目無法排除此器官還有其他受體。"], ["多類受體提供整合多種內分泌訊號的結構基礎。", "實際反應仍須觀察激素濃度與細胞途徑，不能由受體存在推成固定結果。"], ["多訊號整合"], "機制推論", ["兩種訊號必定互相抵消"]),
  question("BIO_R4_Q_S094_11", "BIO_R4_S094", "transfer", 2, "某疾病使全身只有脂肪細胞失去激素丙受體。要評估丙的多器官作用，最適合比較什麼？", ["病人與健康者的髮色", "只測量丙是否由腺體分泌", "比較脂肪與其他仍有受體組織在丙刺激後的反應", "只記錄受試者姓名"], ["髮色不能直接顯示激素丙的標的反應。", "只測分泌無法判斷各組織接收訊號的結果。", "跨組織比較可辨認脂肪特異缺陷與保留的其他作用。", "姓名與內分泌作用範圍無關。"], ["疾病只影響脂肪受體，其他組織可作為比較以呈現丙的多處作用。", "同時測量各組織反應，才能把激素存在與細胞實際反應區分開來。"], ["研究設計"], "探究設計", ["只測激素分泌不測作用"]),
  question("BIO_R4_Q_S094_12", "BIO_R4_S094", "transfer", 3, "廣告說「護肝激素只會進入肝臟，所以不可能影響其他組織」。依激素作用原理，應如何評估？", ["正確，器官名稱能決定激素運送路線", "正確，血液只流經一個器官", "錯誤，所有細胞必定都會反應", "說法缺乏依據，激素可隨血液廣泛運送，作用範圍須看受體分布"], ["器官名稱不能限制循環系統的運送。", "血液會循環通過多個器官與組織。", "只有具有相應受體的細胞才會有效反應。", "是否影響其他組織須檢查受體與實際生理反應。"], ["激素到達範圍通常比作用範圍廣，不能宣稱只會進入某一器官。", "合理評估應要求受體分布與安全性資料，也不能反向推成全身細胞都反應。"], ["健康識讀"], "批判思考", ["器官名稱決定激素去向"]),
);

